  "findings": [
    {
      "check_id": "CKV_AWS_273",
      "title": "Ensure access is controlled through SSO and not AWS IAM defined users",
      "resource": "aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user",
      "severity": "MEDIUM",
      "explanation": "The IAM user is not controlled through SSO, potentially allowing unmanaged access to AWS resources."
    }
  ],
  "patched_code": "resource \"aws_iam_user\" \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\" {\n  name = \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\"\n  path = \"/\"\n\n  # Force user to use SSO by removing access keys\n  # As per https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/iam_user\n  # and https://aws.amazon.com/blogs/security/how-to-disable-access-to-the-aws-management-console-for-an-aws-iam-user/\n  # However, the best practice is to manage users through AWS SSO or Identity Center\n}\n\n# To fully remediate, consider replacing this user with an AWS SSO managed user or using an aws_iam_role with an appropriate trust relationship",
  "fix_summary": "No direct fix is available in Terraform to enforce SSO for an IAM user. However, best practices suggest managing access through AWS SSO or Identity Center instead of IAM users."
}
